`timescale 1ns/1ps

// 300 Hz high-pass followed by 6 kHz low-pass at 32 kHz sample rate.
// Coefficients are signed Q2.30, generated by the fixed-point Python model.
module spike_band_filter #(
    parameter int CHANNELS = 32,
    parameter int CHANNEL_BITS = (CHANNELS > 1 ? $clog2(CHANNELS) : 1),
    parameter bit PIPELINED = 0
) (
    input  logic clk,
    input  logic rst_n,
    input  logic in_valid,
    output logic in_ready,
    input  logic signed [23:0] in_sample,
    input  logic [CHANNEL_BITS-1:0] in_channel,
    output logic out_valid,
    input  logic out_ready,
    output logic signed [23:0] out_sample,
    output logic [CHANNEL_BITS-1:0] out_channel
);
    localparam logic signed [31:0] HP_B0 = 32'sd1029936539;
    localparam logic signed [31:0] HP_B1 = -32'sd2059873079;
    localparam logic signed [31:0] HP_B2 = 32'sd1029936539;
    localparam logic signed [31:0] HP_A1 = -32'sd2058085217;
    localparam logic signed [31:0] HP_A2 = 32'sd987919117;

    localparam logic signed [31:0] LP_B0 = 32'sd200461514;
    localparam logic signed [31:0] LP_B1 = 32'sd400923028;
    localparam logic signed [31:0] LP_B2 = 32'sd200461514;
    localparam logic signed [31:0] LP_A1 = -32'sd497075920;
    localparam logic signed [31:0] LP_A2 = 32'sd225180151;

    logic hp_valid, hp_ready;
    logic signed [23:0] hp_sample;
    logic [CHANNEL_BITS-1:0] hp_channel;

    generate if (PIPELINED) begin : pipelined_sections
    biquad_controller_pipelined #(.CHANNELS(CHANNELS), .CHANNEL_BITS(CHANNEL_BITS))
        high_pass (
            .clk(clk), .rst_n(rst_n),
            .in_valid(in_valid), .in_ready(in_ready),
            .in_sample(in_sample), .in_channel(in_channel),
            .out_valid(hp_valid), .out_ready(hp_ready),
            .out_sample(hp_sample), .out_channel(hp_channel),
            .b0(HP_B0), .b1(HP_B1), .b2(HP_B2),
            .a1(HP_A1), .a2(HP_A2)
        );

    biquad_controller_pipelined #(.CHANNELS(CHANNELS), .CHANNEL_BITS(CHANNEL_BITS))
        low_pass (
            .clk(clk), .rst_n(rst_n),
            .in_valid(hp_valid), .in_ready(hp_ready),
            .in_sample(hp_sample), .in_channel(hp_channel),
            .out_valid(out_valid), .out_ready(out_ready),
            .out_sample(out_sample), .out_channel(out_channel),
            .b0(LP_B0), .b1(LP_B1), .b2(LP_B2),
            .a1(LP_A1), .a2(LP_A2)
        );
    end else begin : reference_sections
    biquad_controller #(.CHANNELS(CHANNELS), .CHANNEL_BITS(CHANNEL_BITS))
        high_pass (
            .clk(clk), .rst_n(rst_n),
            .in_valid(in_valid), .in_ready(in_ready),
            .in_sample(in_sample), .in_channel(in_channel),
            .out_valid(hp_valid), .out_ready(hp_ready),
            .out_sample(hp_sample), .out_channel(hp_channel),
            .b0(HP_B0), .b1(HP_B1), .b2(HP_B2),
            .a1(HP_A1), .a2(HP_A2)
        );

    biquad_controller #(.CHANNELS(CHANNELS), .CHANNEL_BITS(CHANNEL_BITS))
        low_pass (
            .clk(clk), .rst_n(rst_n),
            .in_valid(hp_valid), .in_ready(hp_ready),
            .in_sample(hp_sample), .in_channel(hp_channel),
            .out_valid(out_valid), .out_ready(out_ready),
            .out_sample(out_sample), .out_channel(out_channel),
            .b0(LP_B0), .b1(LP_B1), .b2(LP_B2),
            .a1(LP_A1), .a2(LP_A2)
        );
    end endgenerate
endmodule
